import{_ as a}from"./chunks/academic-mpbench-diagnostic-evidence-envelope.D7J6fTyG.js";import{_ as n,C as s,o as i,c as r,E as o,a2 as l}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"A Failed Multi-Agent Run Can Have More Than One Plausible Cause","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"A Failed Multi-Agent Run Can Have More Than One Plausible Cause","date":"2026-08-26","column":"industry-architecture","category":"academic","article_type":"technical-analysis","edition":"research-center","research_question":"When one failed multi-agent execution supports several plausible causal explanations, should diagnosis force a single root-cause step or preserve a ranked set of hypotheses until evidence justifies a repair?","summary":"MP-Bench makes attribution ambiguity measurable: screened experts frequently disagree about which step induced a multi-agent failure. The safer runtime pattern is to separate immutable trace facts, plural causal hypotheses, consensus/salience, and the eventual repair decision.","sources":"arXiv:2603.25001v1; adobe-research/multi-agent-eval-bench @ b8042d410850672ea5bee4b1031c6cde9028e099; yeonjun-in/MP-Bench; research/reading/A-20260826-01-mp-bench-failure-attribution.md; research/analysis/A-20260826-01-mp-bench-failure-attribution.md","cover":"/assets/covers/academic-mpbench-ranked-diagnostic-evidence-cover-v2.png"},"headers":[],"relativePath":"en/industry/2026-08-26-mpbench-ranked-diagnostic-evidence.md","filePath":"en/industry/2026-08-26-mpbench-ranked-diagnostic-evidence.md","lastUpdated":1787758607000}'),c={name:"en/industry/2026-08-26-mpbench-ranked-diagnostic-evidence.md"};function d(h,e,p,u,m,g){const t=s("ArticleCover");return i(),r("div",null,[o(t,{image:"/assets/covers/academic-mpbench-ranked-diagnostic-evidence-cover-v2.png",kicker:"Industry Architecture · Academic Observation 005",title:"A Failed Multi-Agent Run Can Have More Than One Plausible Cause",summary:"Keep the trace factual, keep causal hypotheses plural, and make the repair decision explicit instead of turning one interpretation into a false certainty.",version:"IA005",status:"Academic Runtime V5 · 2026-08-26",languageHref:"/zh/industry/2026-08-26-mpbench-ranked-diagnostic-evidence",languageLabel:"中文"}),e[0]||(e[0]=l('<h1 id="a-failed-multi-agent-run-can-have-more-than-one-plausible-cause" tabindex="-1">A Failed Multi-Agent Run Can Have More Than One Plausible Cause <a class="header-anchor" href="#a-failed-multi-agent-run-can-have-more-than-one-plausible-cause" aria-label="Permalink to &quot;A Failed Multi-Agent Run Can Have More Than One Plausible Cause&quot;">​</a></h1><p>A multi-agent execution trace can be perfectly stable while its explanation is not.</p><p>Agent A may have collected weak evidence. Agent B may have accepted it too easily. Agent C may have made the visible bad decision. The orchestrator may have failed to intervene. If the task ultimately fails, all four observations can be relevant — yet many debugging systems still insist on writing one value into a field called <code>rootCause</code>.</p><p>That compression is convenient. It can also destroy evidence.</p><p>A 2026 paper from KAIST and Adobe Research, <strong>Rethinking Failure Attribution in Multi-Agent Systems: A Multi-Perspective Benchmark and Evaluation</strong>, turns this problem into a benchmark. Its MP-Bench dataset does not assume that one failed trace has exactly one correct blame step. Instead, several experts annotate the same trace independently, and the benchmark preserves disagreement rather than erasing it.</p><p>The paper does not prove that every production incident has several equally valid causes. It does provide strong primary evidence for a narrower claim: <strong>single-label failure attribution can be too restrictive for multi-agent systems.</strong> The engineering consequence is important. A runtime should treat causal attribution as diagnostic evidence, not as an observed fact.</p><h2 id="the-same-trace-different-reasonable-diagnoses" tabindex="-1">The same trace, different reasonable diagnoses <a class="header-anchor" href="#the-same-trace-different-reasonable-diagnoses" aria-label="Permalink to &quot;The same trace, different reasonable diagnoses&quot;">​</a></h2><p>MP-Bench contains <strong>289 failed execution logs</strong> from <strong>121 distinct multi-agent configurations</strong>. The paper reports 169 hand-crafted MAgenticOne executions and 120 automatically generated CaptainAgent executions, using tasks from GAIA and AssistantBench. Each failed trace is reviewed independently by three screened expert annotators.</p><p>For every step, each annotator records three things: whether the step is failure-inducing, why, and what the agent should ideally have done instead. The public Adobe Research dataset exposes those step-level annotations and rationales in JSON form.</p><p>The important result is not simply that annotators disagree. It is the size and shape of the disagreement.</p><p>Among steps that at least one annotator marked as failure-inducing, the authors report that only <strong>16.2%</strong> were marked by all three experts. <strong>27.8%</strong> were marked by exactly two. <strong>56.1%</strong> were marked by only one. Pairwise disagreement can reach roughly <strong>60%</strong> in the paper&#39;s analysis.</p><p>These are author-reported benchmark statistics; this Academic run did not independently reproduce the complete dataset analysis. But the released dataset structure and paper are enough to establish the benchmark&#39;s intended design: causal interpretation is allowed to remain plural.</p><p>This matters because a trace contains two very different kinds of information:</p><ul><li><strong>what happened</strong> — messages, tool calls, outputs, state transitions and errors;</li><li><strong>what those events caused</strong> — an interpretation of the failure mechanism.</li></ul><p>The first can often be replayed. The second may remain contested.</p><h2 id="mp-bench-does-not-replace-one-answer-with-chaos" tabindex="-1">MP-Bench does not replace one answer with chaos <a class="header-anchor" href="#mp-bench-does-not-replace-one-answer-with-chaos" aria-label="Permalink to &quot;MP-Bench does not replace one answer with chaos&quot;">​</a></h2><p>Preserving several explanations does not mean every explanation receives equal weight.</p><p>MP-Bench converts expert labels into a <strong>consensus-rate ranking</strong>. A step marked as failure-inducing by all three annotators ranks above a step marked by one. The benchmark then evaluates predicted rankings with nDCG rather than asking whether a model matched one oracle step exactly.</p><p>That is a useful design move. It separates two questions that a single-label system mixes together:</p><ol><li><strong>Which causal hypotheses remain plausible?</strong></li><li><strong>Which of them deserve attention first?</strong></li></ol><p>A plural diagnosis can still produce an ordered debugging queue.</p><p>The same distinction appears in the paper&#39;s model experiments. The authors sample failure attributions multiple times and aggregate them into rankings. They report that deterministic decoding is generally less effective than allowing some stochasticity, while higher temperature is not monotonically better. They also report strong results from tested combinations of different model families.</p><p>Those findings are useful, but they need a boundary. Model diversity is not independent causal evidence. Three models can agree because they share the same trace, prompt convention or mistaken assumption. Diversity can generate hypotheses; it does not certify them.</p><p>There is another source-reading nuance worth preserving. The paper states that increasing the number of samples consistently improves performance. Table 4 is almost consistent with that description, but not entirely: for GPT-5.1 on automatic MAS traces, nDCG@5 changes from <strong>0.7819 at N=3</strong> to <strong>0.7769 at N=10</strong>. The broader result can still be useful without turning it into a universal law.</p><h2 id="a-diagnostic-runtime-needs-four-different-objects" tabindex="-1">A diagnostic runtime needs four different objects <a class="header-anchor" href="#a-diagnostic-runtime-needs-four-different-objects" aria-label="Permalink to &quot;A diagnostic runtime needs four different objects&quot;">​</a></h2><p>The following model is a Research Center synthesis derived from MP-Bench&#39;s design. It is <strong>not</strong> a contract proposed by the paper.</p><p><img src="'+a+`" alt="Diagnostic evidence envelope: trace facts support plural hypotheses, which are ranked before a governed repair decision."></p><h3 id="_1-trace-facts" tabindex="-1">1. Trace Facts <a class="header-anchor" href="#_1-trace-facts" aria-label="Permalink to &quot;1. Trace Facts&quot;">​</a></h3><p>Start with immutable execution evidence: agent messages, tool inputs and outputs, external receipts, state transitions, policy decisions, timestamps and errors.</p><p>This layer should answer <strong>what happened</strong> without prematurely answering <strong>why the whole task failed</strong>. If a tool returned HTTP 403, that is a fact. “The access restriction was the root cause” is already a hypothesis.</p><p>A replayable trace gives every later diagnosis the same substrate. Without it, a system can rewrite history every time a new explanation appears.</p><h3 id="_2-failure-hypotheses" tabindex="-1">2. Failure Hypotheses <a class="header-anchor" href="#_2-failure-hypotheses" aria-label="Permalink to &quot;2. Failure Hypotheses&quot;">​</a></h3><p>Store causal explanations as first-class records rather than overwriting one <code>rootCause</code> string.</p><p>A useful hypothesis should carry at least:</p><ul><li>the implicated step, agent or boundary;</li><li>its rationale;</li><li>the perspective or diagnostic method that produced it;</li><li>references to supporting trace evidence;</li><li>counter-evidence;</li><li>evidence identity;</li><li>confidence or support state;</li><li>relationships to compatible or mutually exclusive hypotheses.</li></ul><p>This makes disagreement inspectable. It also allows a later deterministic check, new external evidence or human review to strengthen one explanation without deleting the others.</p><h3 id="_3-consensus-salience" tabindex="-1">3. Consensus / Salience <a class="header-anchor" href="#_3-consensus-salience" aria-label="Permalink to &quot;3. Consensus / Salience&quot;">​</a></h3><p>Now rank the hypotheses.</p><p>Consensus can matter: three independent experts pointing to the same step is different from one speculative interpretation. Severity matters too. A low-confidence hypothesis involving authorization bypass may deserve attention before a high-confidence cosmetic failure.</p><p>But <strong>consensus and independence must stay separate</strong>.</p><p>Three samples from one model are three perspectives, not three independent evidence sources. Three agents all reading the same fabricated source can agree perfectly and still be wrong. A governed runtime should therefore track at least two axes:</p><ul><li><strong>perspective convergence</strong> — how many diagnostic paths support the hypothesis;</li><li><strong>evidence independence</strong> — whether those paths depend on genuinely different evidence families.</li></ul><p>MP-Bench directly motivates the first axis. The second is an engineering requirement we add to avoid turning agreement into false verification.</p><h3 id="_4-repair-decision" tabindex="-1">4. Repair Decision <a class="header-anchor" href="#_4-repair-decision" aria-label="Permalink to &quot;4. Repair Decision&quot;">​</a></h3><p>Operations eventually need one next action.</p><p>This is where systems often force the diagnosis to become singular: “We can only make one repair, therefore there must be one root cause.” That does not follow.</p><p>A repair decision can be singular while causality remains plural. The system can choose the safest reversible intervention because it addresses two high-salience hypotheses at low cost. It can record why that repair was authorized and what evidence must be collected afterward.</p><p>If the repair works, that is new evidence. It does not automatically prove that its motivating hypothesis was the unique cause.</p><h2 id="plural-diagnosis-can-make-action-more-disciplined-not-less" tabindex="-1">Plural diagnosis can make action more disciplined, not less <a class="header-anchor" href="#plural-diagnosis-can-make-action-more-disciplined-not-less" aria-label="Permalink to &quot;Plural diagnosis can make action more disciplined, not less&quot;">​</a></h2><p>Consider a failed research-agent run:</p><ul><li>one hypothesis says the search agent accepted a low-quality source;</li><li>another says the analysis agent overstated what the source supported;</li><li>a third says the publication gate failed to detect the overclaim.</li></ul><p>A scalar root-cause field forces someone to choose. A diagnostic evidence set can preserve all three and still decide that the lowest-risk repair is to tighten the publication evidence gate first, because that change blocks the harmful outcome regardless of which upstream explanation later proves most important.</p><p>That is not indecision. It is separating <strong>causal belief</strong> from <strong>risk control</strong>.</p><p>This separation is especially useful in multi-agent systems because failures can propagate. The visible error is often downstream of the first weak state transition, and the first weak transition may itself have been recoverable. “Who caused it?” and “where should we intervene?” are related questions, not identical ones.</p><h2 id="what-mp-bench-actually-supports-—-and-what-it-does-not" tabindex="-1">What MP-Bench actually supports — and what it does not <a class="header-anchor" href="#what-mp-bench-actually-supports-—-and-what-it-does-not" aria-label="Permalink to &quot;What MP-Bench actually supports — and what it does not&quot;">​</a></h2><p>The paper provides concrete primary-source evidence for several points:</p><ul><li>screened experts can disagree substantially about failure-inducing steps in the same MAS trace;</li><li>a ranking-based evaluation can preserve that disagreement while prioritizing high-consensus steps;</li><li>the paper&#39;s tested LLM systems can produce useful multi-perspective rankings under its protocol;</li><li>stochastic and cross-model diversity can affect benchmark performance.</li></ul><p>It does <strong>not</strong> establish:</p><ul><li>that every real incident has multiple valid root causes;</li><li>that expert consensus proves causal truth;</li><li>that a multi-LLM ensemble is universally the best production diagnostician;</li><li>that its LLM-assisted consolidation and judging are neutral measurement primitives;</li><li>that the reported results generalize to software engineering, scientific agents or enterprise digital employees;</li><li>crash-safe or exactly-once semantics for a production diagnostic runtime.</li></ul><p>The benchmark is also deliberately quality-first rather than broad. The authors identify domain coverage and MAS framework diversity as limitations. The arXiv record says the paper is under review. This run found first-party paper and repository evidence but did not identify an independent reproduction of the complete experimental results.</p><p>The official Adobe Research dataset repository also carries a non-commercial research license. The existence of open code or data should not be read as permission for commercial product integration.</p><h2 id="the-operational-rule-do-not-let-explanation-overwrite-evidence" tabindex="-1">The operational rule: do not let explanation overwrite evidence <a class="header-anchor" href="#the-operational-rule-do-not-let-explanation-overwrite-evidence" aria-label="Permalink to &quot;The operational rule: do not let explanation overwrite evidence&quot;">​</a></h2><p>A robust failure record can therefore look less like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rootCause = &quot;Agent C, step 17&quot;</span></span></code></pre></div><p>and more like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>trace_facts      = immutable</span></span>
<span class="line"><span>failure_hypotheses = append-only, provenance-aware</span></span>
<span class="line"><span>consensus        = ranked, not truth-equivalent</span></span>
<span class="line"><span>repair_decision  = explicit, bounded, verifiable</span></span></code></pre></div><p>That structure creates a useful asymmetry: <strong>facts become harder to rewrite, while hypotheses remain easy to revise.</strong></p><p>For multi-agent reliability, that is the right direction. The system should become more certain only when new evidence justifies it — not because a schema demanded one value.</p><h2 id="what-remains-open" tabindex="-1">What remains open <a class="header-anchor" href="#what-remains-open" aria-label="Permalink to &quot;What remains open&quot;">​</a></h2><p>MP-Bench makes attribution ambiguity measurable, but several hard production questions remain.</p><p>How should a runtime detect correlated consensus when several diagnostic agents share one model family? What evidence is strong enough to promote a plausible hypothesis into an operationally decisive one? Can deterministic dependency graphs eliminate impossible explanations before LLM analysis? How should post-repair evidence update causal belief without rewriting the historical record?</p><p>Most importantly, the next benchmark should test whether multi-perspective diagnosis actually improves repair quality on real, high-consequence multi-agent incidents — not only whether its rankings align with expert annotations.</p><p>Until then, the useful lesson is narrower and still important: <strong>one failed run does not require one causal story. Preserve the evidence first; choose the repair second.</strong></p><h2 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h2><ol><li>Yeonjun In et al., <strong>Rethinking Failure Attribution in Multi-Agent Systems: A Multi-Perspective Benchmark and Evaluation</strong>, arXiv:2603.25001v1, 2026-03-26 — <a href="https://arxiv.org/abs/2603.25001" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.25001</a></li><li>Full paper HTML — <a href="https://arxiv.org/html/2603.25001" target="_blank" rel="noreferrer">https://arxiv.org/html/2603.25001</a></li><li>Adobe Research, <strong>multi-agent-eval-bench</strong>, inspected at <code>b8042d410850672ea5bee4b1031c6cde9028e099</code> — <a href="https://github.com/adobe-research/multi-agent-eval-bench" target="_blank" rel="noreferrer">https://github.com/adobe-research/multi-agent-eval-bench</a></li><li>Paper-linked code repository — <a href="https://github.com/yeonjun-in/MP-Bench" target="_blank" rel="noreferrer">https://github.com/yeonjun-in/MP-Bench</a></li><li>Governed Deep Reading — <code>research/reading/A-20260826-01-mp-bench-failure-attribution.md</code></li><li>Governed Research Analysis — <code>research/analysis/A-20260826-01-mp-bench-failure-attribution.md</code></li></ol><p><strong>Evidence boundary:</strong> Items 1–4 are the paper and first-party research/code artifacts. They support public facts and source-reported results but do not constitute independent reproduction. The four-layer diagnostic evidence envelope is explicitly a Research Center interpretation built on that evidence.</p>`,76))])}const y=n(c,[["render",d]]);export{v as __pageData,y as default};
